NAME = 'vlsJoNT: Het Nieuwe Testament by Nicolaas De Jonge'
BOOK = 'II Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus en Silvanus en Timotheüs, aan de gemeente der Thessalonikers, in God onzen Vader en den Heere Jezus Christus:',
        2: 'genade zij ulieden en vrede van God onzen Vader en van den Heere Jezus Christus!',
        3: 'Wij moeten God altijd over u danken, broeders, gelijk betamelijk is, omdat uw geloof zeer aanwast en omdat de liefde van u allen tot malkander zeer toeneemt,',
        4: 'zoodat wij zelf ook in u roemen in de gemeenten Gods, over uw volhardingen geloof in al uw vervolgingen en de verdrukkingen die gij verdraagt,',
        5: 'tot een bewijs van Gods rechtvaardig oordeel, opdat gij waardig zoudt geacht worden het koninkrijk Gods waarvoor gij ook lijdt.',
        6: 'Want het is rechtvaardig bij God om verdrukking te vergelden aan uw verdrukkers,',
        7: 'en aan u die verdrukt wordt verkwikking met ons, in de openbaring van den Heere Jezus van den hemel, met de engelen zijner macht, in vlammend vuur,',
        8: 'wraak doende aan degenen die God niet kennen en aan degenen die het Evangelie van onzen Heere Jezus Christus niet gehoorzaam zijn,',
        9: 'die gestraft zullen worden met een eeuwig verderf van het aangezicht des Heeren en van de glorie zijner sterkte,',
        10: 'als Hij zal komen om de glorie te ontvangen in zijn heiligen en zich wonderbaar te vertoonen in allen die gelooven, in dien dag; want ons getuigenis aan ulieden is geloofd geworden.',
        11: 'Tot dien einde bidden wij ook altijd voor ulieden, opdat onze God u uw roeping waardig moge maken en Hij al het welbehagen zijner goedheid en het werk des geloofs met kracht vervullen moge,',
        12: 'opdat de Naam van onzen Heere Jezus Christus in u de glorie ontvangen moge, en gij in Hem, naar de genade van onzen God en van den Heere Jezus Christus.',
    },
    2: {
        1: 'Doch wij bidden u, broeders, wat aangaat de verschijning van onzen Heere Jezus Christus, en onze bijeenvergadering met Hem;',
        2: 'laat u toch niet lichtelijk beroeren van gemoed, noch verschrikken, zoo min door een geest, als door een woord of door een brief die door ons zou geschreven zijn, alsof de dag des Heeren voor de deur staat.',
        3: 'Laat niemand u verleiden op eenigerlei wijze, want die dag des Heeren komt niet als eerst de afval niet gekomen is en openbaar geworden is de mensch der wetteloosheid, de zoon des verderfs,',
        4: 'de tegenstander en verheffer van zich zelven boven al wat God genoemd wordt of wat godsdienstig vereerd wordt, zoodat hij zich zelven zal zetten in den tempel Gods, zich zelven voordoende alsof hij God is.',
        5: 'Hebt gij niet onthouden dat ik, toen ik nog bij ulieden was, u deze dingen gezegd heb?',
        6: 'En nu weet gij wel wat hem terughoudt opdat hij op zijn tijd openbaar worde.',
        7: 'Want de verborgenheid der wetteloosheid werkt alreeds; alleenlijk die hem terughoudt moet nog uit het midden weggedaan zijn,',
        8: 'en alsdan zal de wettelooze openbaar worden, dien de Heere Jezus vernielen zal door den adem zijns monds en vernietigen zal door de verschijning zijner toekomst;',
        9: 'wiens toekomst is naaide werking des Satans, in alle kracht en teekenen en mirakelen der leugen,',
        10: 'en in alle verleiding van onrechtvaardigheid voor degenen die verloren gaan, omdat zij de liefde der waarheid niet hebben aangenomen om behouden te worden.',
        11: 'En daarom zendt God hun een kracht van doling, om ze in den leugen te doen gelooven,',
        12: 'opdat zij allen zouden geoordeeld worden die niet geloofd hebben in de waarheid, maar die een welbehagen gehad hebben in de onrechtvaardigheid.',
        13: 'Doch wij moeten God altijd danken over ulieden, broeders die van den Heere bemind zijt, omdat God u verkozen heeft van den beginne tot behoudenis, in heiligmaking des Geestes en geloof der waarheid,',
        14: 'waartoe Hij u ook geroepen heeft door ons Evangelie, tot bekoming der glorie van onzen Heere Jezus Christus.',
        15: 'Zoo dan, broeders, staat vast en behoudt de overleveringen die gij geleerd hebt hetzij door woord, hetzij door onzen brief.',
        16: 'En onze Heere Jezus Christus zelf en onze God en Vader die ons bemind heeft en een eeuwige vertroosting gegeven heeft, en goede hope in genade,',
        17: 'die moge uw harten vertroosten en versterken in alle goed werk en woord.',
    },
    3: {
        1: 'Tenslotte, broeders, bidt voor ons, opdat het woord des Heeren verspreid worden moge en de glorie ontvange, zooals het ook is bij ulieden,',
        2: 'en opdat wij verlost mogen worden van de ongeregelde en kwade menschen; want het geloof is niet gemeen aan allen.',
        3: 'Doch de Heere is getrouw, die ulieden versterken zal en bewaren van het kwaad.',
        4: 'En wij vertrouwen in den Heere van ulieden dat gij doet en doen zult wat wij gebieden.',
        5: 'Doch de Heere bestiere uw harten tot de liefde Gods en tot de volharding van Christus.',
        6: 'En wij gebieden u, broeders, in den Naam van onzen Heere Jezus Christus, u te onttrekken van allen broeder die ongeregeld wandelt, en niet naar de overlevering die zij van ons ontvangen hebben.',
        7: 'Want gij weet zelf hoe noodig het is ons na te volgen, omdat wij ons niet ongeregeld gedragen hebben onder u;',
        8: 'ook hebben wij geen brood van u voor niet gegeten, maar nacht en dag werkende in arbeid en moeite, om niemand van u te bezwaren.',
        9: 'Niet dat wij daartoe geen macht hadden, maar om zelf ulieden een voorbeeld te geven om ons na te volgen.',
        10: 'Want toen wij bij u waren hebben wij dit gezegd dat, als iemand niet wil werken dan moet hij ook niet eten.',
        11: 'Want wij hooren dat sommigen onder u ongeregeld wandelen, niet werkende maar ledig loopende.',
        12: 'Doch den zoodanige gebieden en vermanen wij in den Heere Jezus Christus, om stillekens te werken en hun eigen brood te eten.',
        13: 'Maar gij, broeders, houdt niet op van goed te doen.',
        14: 'En als iemand niet gehoorzaamt aan ons woord door dezen brief, houdt hem in het oog; hebt geen gemeenschap met hem opdat hij beschaamd worde;',
        15: 'en beschouwt hem niet als een vijand, maar bestraft hem als een broeder.',
        16: 'Doch de Heere de vredes zelf geve u den vrede ten allen tijde, in alle wijze: De Heer zij met u allen!',
        17: 'De groetenis met mijn hand, van Paulus. Dit is een teeken in eiken brief. Alzoo schrijf ik.',
        18: 'De genade van onze Heere Jezus Christus zij me u allen. Amen.',
    },
}
